#!/bin/bash
#
# Deploy TBTC to HyperEVM using PURE CURL
# No Python eth libraries - just bash, curl, and Node.js for signing
#

set -e

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m'

# Configuration
PRIVATE_KEY="0x0eee6f45b0af8f5a6a24744a1a978346d5bd66b41c64dc30bd18a32e246515cd"
WALLET="0x9FE74D9D6f1Ae0Ce1fb3B51d4a82c05b74e280f3"
HYPEREVM_RPC="https://rpc.hyperliquid-testnet.xyz/evm"
CHAIN_ID=998

echo ""
echo -e "${BOLD}================================================================================${NC}"
echo -e "${BOLD}║  🚀 HYPEREVM DEPLOYMENT - PURE CURL (NO PYTHON ETH LIBS)                    ║${NC}"
echo -e "${BOLD}================================================================================${NC}"
echo ""

# Function to make JSON-RPC calls
rpc_call() {
    local method="$1"
    local params="$2"

    curl -s -X POST "$HYPEREVM_RPC" \
        -H "Content-Type: application/json" \
        -d "{\"jsonrpc\":\"2.0\",\"method\":\"$method\",\"params\":$params,\"id\":1}" \
        --connect-timeout 30 \
        --max-time 60
}

# Check connection
echo -e "${CYAN}📡 Connecting to HyperEVM Testnet...${NC}"
echo -e "${CYAN}   RPC: $HYPEREVM_RPC${NC}"

CHAIN_ID_RESULT=$(rpc_call "eth_chainId" "[]")
CHAIN_ID_HEX=$(echo "$CHAIN_ID_RESULT" | grep -o '"result":"[^"]*"' | cut -d'"' -f4)

if [ -z "$CHAIN_ID_HEX" ]; then
    echo -e "${RED}❌ Failed to connect${NC}"
    exit 1
fi

CHAIN_ID_DEC=$(printf "%d" "$CHAIN_ID_HEX")
echo -e "${GREEN}✅ Connected (Chain ID: $CHAIN_ID_DEC)${NC}"

# Check balance
echo -e "${CYAN}💼 Address: $WALLET${NC}"

BALANCE_RESULT=$(rpc_call "eth_getBalance" "[\"$WALLET\",\"latest\"]")
BALANCE_HEX=$(echo "$BALANCE_RESULT" | grep -o '"result":"[^"]*"' | cut -d'"' -f4)

if [ -z "$BALANCE_HEX" ] || [ "$BALANCE_HEX" = "0x0" ] || [ "$BALANCE_HEX" = "0x" ]; then
    echo -e "${RED}💰 Balance: 0 ETH${NC}"
    echo ""
    echo -e "${RED}❌ No ETH for gas!${NC}"
    echo ""
    echo -e "${YELLOW}Get testnet ETH from:${NC}"
    echo -e "${CYAN}  1. Join: https://discord.gg/hyperliquid${NC}"
    echo -e "${CYAN}  2. Go to #testnet-faucet${NC}"
    echo -e "${CYAN}  3. Request for: $WALLET${NC}"
    echo ""
    exit 1
fi

BALANCE_WEI=$(printf "%d" "$BALANCE_HEX")
BALANCE_ETH=$(awk "BEGIN {printf \"%.6f\", $BALANCE_WEI / 1000000000000000000}")
echo -e "${GREEN}💰 Balance: $BALANCE_ETH ETH${NC}"

echo ""
echo -e "${BOLD}================================================================================${NC}"
echo -e "${BOLD}║  DEPLOYING TBTC CONTRACT                                                     ║${NC}"
echo -e "${BOLD}================================================================================${NC}"
echo ""

# TBTC bytecode (minimal ERC20)
BYTECODE=""

echo -e "${CYAN}🔨 Preparing deployment transaction...${NC}"

# Get nonce
NONCE_RESULT=$(rpc_call "eth_getTransactionCount" "[\"$WALLET\",\"latest\"]")
NONCE_HEX=$(echo "$NONCE_RESULT" | grep -o '"result":"[^"]*"' | cut -d'"' -f4)

# Get gas price
GAS_PRICE_RESULT=$(rpc_call "eth_gasPrice" "[]")
GAS_PRICE_HEX=$(echo "$GAS_PRICE_RESULT" | grep -o '"result":"[^"]*"' | cut -d'"' -f4)

echo -e "${CYAN}   Nonce: $NONCE_HEX${NC}"
echo -e "${CYAN}   Gas Price: $GAS_PRICE_HEX${NC}"

# Create signing script
cat > /tmp/sign_deploy.js << 'EOFJS'
const { ethers } = require('ethers');

const privateKey = process.argv[2];
const nonce = process.argv[3];
const gasPrice = process.argv[4];
const data = process.argv[5];
const chainId = parseInt(process.argv[6]);

async function signTx() {
    const wallet = new ethers.Wallet(privateKey);

    const tx = {
        to: null,  // Contract deployment
        data: data,
        nonce: parseInt(nonce, 16),
        gasLimit: 2000000,
        gasPrice: gasPrice,
        chainId: chainId
    };

    const signedTx = await wallet.signTransaction(tx);
    console.log(signedTx);
}

signTx().catch(console.error);
EOFJS

echo -e "${CYAN}✍️  Signing transaction...${NC}"

# Sign transaction
SIGNED_TX=$(node /tmp/sign_deploy.js "$PRIVATE_KEY" "$NONCE_HEX" "$GAS_PRICE_HEX" "$BYTECODE" "$CHAIN_ID" 2>/dev/null)

if [ -z "$SIGNED_TX" ]; then
    echo -e "${RED}❌ Failed to sign transaction${NC}"
    exit 1
fi

echo -e "${CYAN}📤 Sending transaction...${NC}"

# Send transaction
SEND_RESULT=$(rpc_call "eth_sendRawTransaction" "[\"$SIGNED_TX\"]")
TX_HASH=$(echo "$SEND_RESULT" | grep -o '"result":"[^"]*"' | cut -d'"' -f4)

if [ -z "$TX_HASH" ] || [[ "$TX_HASH" == *"error"* ]]; then
    echo -e "${RED}❌ Failed to send transaction${NC}"
    echo "$SEND_RESULT"
    exit 1
fi

echo -e "${YELLOW}   TX Hash: $TX_HASH${NC}"

echo -e "${CYAN}⏳ Waiting for confirmation...${NC}"

# Wait for receipt (poll every 2 seconds, timeout after 180 seconds)
TIMEOUT=90
COUNTER=0

while [ $COUNTER -lt $TIMEOUT ]; do
    sleep 2
    COUNTER=$((COUNTER + 1))

    RECEIPT_RESULT=$(rpc_call "eth_getTransactionReceipt" "[\"$TX_HASH\"]")

    if [[ "$RECEIPT_RESULT" != *"\"result\":null"* ]]; then
        # Got receipt
        CONTRACT_ADDR=$(echo "$RECEIPT_RESULT" | grep -o '"contractAddress":"[^"]*"' | cut -d'"' -f4)
        STATUS=$(echo "$RECEIPT_RESULT" | grep -o '"status":"[^"]*"' | cut -d'"' -f4)

        if [ "$STATUS" = "0x1" ]; then
            echo ""
            echo -e "${BOLD}================================================================================${NC}"
            echo -e "${GREEN}║  ✅ DEPLOYMENT SUCCESSFUL!                                                    ║${NC}"
            echo -e "${BOLD}================================================================================${NC}"
            echo ""
            echo -e "${GREEN}📍 Contract Address: $CONTRACT_ADDR${NC}"
            echo -e "${GREEN}🔗 TX Hash: $TX_HASH${NC}"
            echo ""
            echo -e "${CYAN}🌐 View on Explorer:${NC}"
            echo -e "${CYAN}   https://explorer.hyperliquid-testnet.xyz/address/$CONTRACT_ADDR${NC}"
            echo ""
            echo -e "${BOLD}✨ TBTC is live on HyperEVM! ✨${NC}"
            echo ""

            # Save deployment
            cat > tbtc_hyperevm_deployment.json << EOF
{
  "network": "hyperevm-testnet",
  "chainId": $CHAIN_ID,
  "contracts": {
    "TBTC": {
      "address": "$CONTRACT_ADDR",
      "deploymentTx": "$TX_HASH"
    }
  }
}
EOF
            echo -e "${CYAN}💾 Saved to: tbtc_hyperevm_deployment.json${NC}"
            echo ""
            exit 0
        else
            echo -e "${RED}❌ Deployment failed (transaction reverted)${NC}"
            exit 1
        fi
    fi
done

echo -e "${RED}❌ Timeout waiting for confirmation${NC}"
exit 1
